	      // TODO: Extend to handle non-empty where clauses.
	      case STraitTypeWhere(_,SAnyType(_),_) => {}
	      case STraitTypeWhere(_,STraitType(_,name,_,_),_) =>
		checkDeclAcyclicity(name, decl::children, errors)

